int cache_get(cache_t *c, const char *key, char *out, size_t n) {
    pthread_rwlock_rdlock(&c->lock);
    entry_t *e = cache_find(c, key);
    if (e && !expired(e)) { copy_out(e, out, n); pthread_rwlock_unlock(&c->lock); return 0; }
    pthread_rwlock_unlock(&c->lock);          /* never load while holding the read lock */
    char *v = source_read(key);               /* source of truth on a miss */
    pthread_rwlock_wrlock(&c->lock);
    cache_store(c, key, v, now_plus(c->ttl)); /* populate with an expiry */
    pthread_rwlock_unlock(&c->lock);
    return copy_out_value(v, out, n);
}
